#include <bits/stdc++.h>
using namespace std;
class Solution {public:long long maximumSumOfHeights(vector<int>& a){int n=a.size();vector<long long>L(n),R(n);vector<int> st;for(int i=0;i<n;++i){while(!st.empty()&&a[st.back()]>a[i])st.pop_back();int j=st.empty()?-1:st.back();L[i]=(j<0?0:L[j])+1LL*(i-j)*a[i];st.push_back(i);}st.clear();for(int i=n-1;i>=0;--i){while(!st.empty()&&a[st.back()]>a[i])st.pop_back();int j=st.empty()?n:st.back();R[i]=(j==n?0:R[j])+1LL*(j-i)*a[i];st.push_back(i);}long long ans=0;for(int i=0;i<n;++i)ans=max(ans,L[i]+R[i]-a[i]);return ans;}};
